import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    arr = [int(x) for x in data[1:1 + n]]
    key = int(data[1 + n]) if len(data) > 1 + n else None

    found = -1
    for i in range(n):
        if arr[i] == key:
            found = i
            break

    if found != -1:
        print(found)
    else:
        print("Not Found")

if __name__ == "__main__":
    main()
